#include "mspa/psychology/memory.hpp"
#include <algorithm>
#include <cmath>
namespace mspa {namespace{std::uint64_t next(const AgentPsychState&a){std::uint64_t n=1;for(const auto&m:a.memories)n=std::max(n,m.id.value()+1);return n;}}
Result<MemoryId>MemorySystem::remember(AgentPsychState&a,const Proposition&p,float imp,PsychTime t,float load,float certainty,BeliefSource src,const std::vector<AgentId>&parts)const{if(!p.predicate.valid()||!p.name_space.valid()||!std::isfinite(imp))return make_error(ErrorCode::InvalidArgument,"invalid memory");MemoryState m{};m.id=MemoryId(next(a));m.proposition=p;m.importance=std::clamp(imp,0.0f,1.0f);m.emotional_load=std::clamp(load,-1.0f,1.0f);m.certainty=std::clamp(certainty,0.0f,1.0f);m.source=src;m.participants=parts;m.event_time=t;m.last_reactivated_at=t;a.memories.push_back(m);return m.id;}Result<MemoryId>MemorySystem::remember(AgentPsychState&a,PredicateId p,float imp,PsychTime t)const{Proposition q{};q.predicate=p;q.name_space=NamespaceId(1);return remember(a,q,imp,t);}Result<void>MemorySystem::reactivate(AgentPsychState&a,MemoryId id,PsychTime now)const{auto it=std::find_if(a.memories.begin(),a.memories.end(),[&](const auto&m){return m.id==id;});if(it==a.memories.end())return make_error(ErrorCode::InvalidArgument,"memory does not exist");++it->reactivations;it->importance=std::clamp(it->importance+0.05f,0.0f,1.0f);it->last_reactivated_at=now;return {};}std::vector<const MemoryState*>MemorySystem::recall(const AgentPsychState&a,PredicateId p,std::size_t limit)const{std::vector<const MemoryState*>v;for(const auto&m:a.memories)if(m.proposition.predicate==p)v.push_back(&m);std::stable_sort(v.begin(),v.end(),[](auto*x,auto*y){return x->importance>y->importance;});if(v.size()>limit)v.resize(limit);return v;}void MemorySystem::compact(AgentPsychState&a,std::size_t max)const{if(a.memories.size()<=max)return;std::stable_sort(a.memories.begin(),a.memories.end(),[](const auto&x,const auto&y){const float sx=x.importance+0.15f*std::abs(x.emotional_load)+0.02f*static_cast<float>(x.reactivations);const float sy=y.importance+0.15f*std::abs(y.emotional_load)+0.02f*static_cast<float>(y.reactivations);return sx>sy;});a.memories.resize(max);}void MemorySystem::consolidate(AgentPsychState&a,PsychTime now,std::size_t max,float penalty)const{for(auto&m:a.memories){if(now>=m.event_time){float age=static_cast<float>(now.ticks()-m.event_time.ticks());float resilience=0.5f*m.importance+0.3f*std::abs(m.emotional_load)+0.02f*static_cast<float>(m.reactivations);m.importance=std::clamp(m.importance-age*std::max(0.0f,penalty)*(1.0f-resilience),0.0f,1.0f);}}compact(a,max);}
}
